#!/bin/bash
# =====================================================
# AI Booking + Luxe — Komplett deploy (begge sider)
# Root:  https://bonusvarsel-ai-booking.web.app
# Luxe:  https://bonusvarsel-ai-booking.web.app/luxe
# =====================================================
# Kjør: bash ~/Downloads/08_deploy_luxe.sh
# =====================================================

set -e

PROJECT_ID="bonusvarsel-ai-booking"
DEPLOY_DIR="$HOME/booking-luxe-deploy"

echo "════════════════════════════════════════════════"
echo "  Deploy: Root-demo + Luxe-demo"
echo "════════════════════════════════════════════════"

command -v firebase >/dev/null 2>&1 || { echo "❌ Firebase CLI mangler."; exit 1; }

rm -rf "$DEPLOY_DIR"
mkdir -p "$DEPLOY_DIR/public/luxe"

cat > "$DEPLOY_DIR/firebase.json" << 'EOF'
{
  "hosting": {
    "public": "public",
    "ignore": ["firebase.json", "**/.*"],
    "headers": [{ "source": "**", "headers": [{ "key": "Cache-Control", "value": "no-cache" }] }]
  }
}
EOF

cat > "$DEPLOY_DIR/.firebaserc" << EOF
{ "projects": { "default": "$PROJECT_ID" } }
EOF

python3 -c "
import base64
main_html = base64.b64decode('').decode()
luxe_html = base64.b64decode('').decode()
open('$DEPLOY_DIR/public/index.html', 'w').write(main_html)
open('$DEPLOY_DIR/public/luxe/index.html', 'w').write(luxe_html)
print('✅ Begge sider skrevet')
"

cd "$DEPLOY_DIR"
firebase use "$PROJECT_ID"
echo "🚀 Deployer..."
firebase deploy --only hosting --project "$PROJECT_ID"

echo ""
echo "════════════════════════════════════════════════"
echo "  ✅ LIVE!"
echo "  🔗 Hoveddemo: https://bonusvarsel-ai-booking.web.app"
echo "  🔗 Luxe:      https://bonusvarsel-ai-booking.web.app/luxe"
echo "════════════════════════════════════════════════"
